#include "umicom/editor/workbench/breadcrumb_strip.h"
int main(void){ UmiEditorWbBreadcrumbStrip s; umi_editor_wb_breadcrumb_strip_init(&s); if(umi_editor_wb_breadcrumb_strip_append(&s,"one",1U)!=UMI_STATUS_OK)return 1; if(umi_editor_wb_breadcrumb_strip_append(&s,"two",2U)!=UMI_STATUS_OK)return 2; if(umi_editor_wb_breadcrumb_strip_activate(&s,1U)!=UMI_STATUS_OK||s.active_index!=1U)return 3; return 0; }
